parameters.jsCode:
const input = $input.first().json;

// Récupérer les données du produit
const produitData = $('IF Produit Found').first().json;

// Récupérer l'analyse depuis "Code in JavaScript"
const analyseData = $('Code in JavaScript').first().json;

// Parser la réponse JSON du prompt Flux Kontext
let promptData;
try {
  // GPT avec jsonOutput: true retourne directement le JSON
  if (input.prompt_flux_kontext) {
    promptData = input;
  } else {
    const content = input.message?.content || (Array.isArray(input.content) ? input.content[0].text : input.content) || input.text || JSON.stringify(input);
    const cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    promptData = JSON.parse(cleanContent);
  }
} catch (e) {
  // Fallback si parsing échoue
  promptData = {
    prompt_flux_kontext: `Professional product photography of a ${analyseData.type_produit || 'product'} on a modern office desk with natural lighting, blurred background with subtle orange and green accent colors, clean minimalist style, high quality commercial photography, any visible text must be in French`,
    contexte_choisi: 'Bureau moderne',
    elements_arriere_plan: ['desk', 'natural light'],
    ambiance_lumiere: 'Natural daylight',
    justification: 'Contexte professionnel standard'
  };
}

return {
  json: {
    // Données produit
    id: produitData.id,
    reference: produitData.reference,
    nom_produit: produitData.nom_produit,
    categorie: produitData.categorie,
    url_image: produitData.url_image,
    couleurs_dispo: produitData.couleurs_dispo,

    // Analyse du produit
    analyse: {
      type_produit: analyseData.type_produit,
      couleur_principale: analyseData.couleur_principale,
      couleurs_secondaires: analyseData.couleurs_secondaires || [],
      materiau: analyseData.materiau,
      caracteristiques: analyseData.caracteristiques || [],
      taille: analyseData.taille,
      contexte_utilisation_suggere: analyseData.contexte_utilisation_suggere
    },

    // Prompt Flux Kontext
    prompt_flux_kontext: promptData.prompt_flux_kontext,
    contexte_choisi: promptData.contexte_choisi,
    elements_arriere_plan: promptData.elements_arriere_plan || [],
    ambiance_lumiere: promptData.ambiance_lumiere,
    justification_contexte: promptData.justification
  }
};

const falResponse = $input.first().json;
const prevData = $('Parse Prompt JSON').first().json;

// Extraire l'URL de l'image generee par Fal.ai
let imageUrl;
if (falResponse.images && falResponse.images.length > 0) {
  imageUrl = falResponse.images[0].url;
} else if (falResponse.image) {
  imageUrl = falResponse.image.url || falResponse.image;
} else if (falResponse.output) {
  imageUrl = falResponse.output;
} else {
  // Fallback: utiliser l'image originale
  imageUrl = prevData.url_image;
}

return {
  json: {
    ...prevData,
    image_transformee_url_temp: imageUrl,
    flux_kontext_success: imageUrl !== prevData.url_image
  }
};

const cloudinaryResponse = $input.first().json;
const prevData = $('Parse Fal Response').first().json;

return {
  json: {
    ...prevData,
    image_transformee_url: cloudinaryResponse.secure_url || cloudinaryResponse.url,
    cloudinary_public_id: cloudinaryResponse.public_id
  }
};

