const input = $input.first().json;
const prevData = $('Parse Cloudinary Response').first().json;

// Récupérer le contenu du post
let postData;

// Anthropic/GPT avec jsonOutput: true retourne content comme OBJET ou tableau directement
if (input.message?.content && typeof input.message.content === 'object' && !Array.isArray(input.message.content)) {
  // Content est déjà un objet JSON
  postData = input.message.content;
} else {
  // Fallback : essayer de parser si c'est une string
  try {
    const content = input.message?.content || (Array.isArray(input.content) ? input.content[0].text : input.content) || input.text || JSON.stringify(input);
    const cleanContent = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    postData = JSON.parse(cleanContent);
  } catch (e) {
    // Fallback ultime si parsing échoue
    postData = {
      hook: `🌟 Découvrez notre ${prevData.nom_produit} !`,
      corps: `Un ${prevData.analyse?.type_produit || 'produit'} de qualité pour vos campagnes de communication.\n\nPersonnalisez-le aux couleurs de votre entreprise pour un impact maximal auprès de vos clients et collaborateurs.`,
      cta: 'Quel goodies fera la différence pour votre prochaine campagne ?',
      hashtags: '#goodies #objetspub #B2B #communication #rapidpub',
      angle_choisi: 'Présentation produit standard'
    };
  }
}

return {
  json: {
    produit_id: prevData.produit_id,
    reference_produit: prevData.reference,
    nom_produit: prevData.nom_produit,
    categorie_produit: prevData.categorie,
    hook: postData.hook,
    corps: postData.corps,
    cta: postData.cta,
    hashtags: postData.hashtags,
    image_originale_url: prevData.url_image,
    image_transformee_url: prevData.image_transformee_url,
    prompt_transformation: prevData.prompt_flux_kontext,
    analyse_produit: prevData.analyse,
    angle_choisi: postData.angle_choisi,
    ton_utilise: postData.ton_utilise,
    contexte_image: prevData.contexte_choisi,
    commentaire_lien: postData.commentaire_lien || 'Découvrez ce produit et tous nos goodies personnalisables 👉 https://www.rapid-pub.com'
  }
};

const error = $input.first().json;

// Essayer de recuperer les infos produit
let produitInfo = {};
try {
  const produit = $('Get Produit A_Poster').first().json;
  produitInfo = {
    produit_id: produit?.id || 'unknown',
    nom_produit: produit?.nom_produit || 'Inconnu',
    reference: produit?.reference || 'N/A'
  };
} catch (e) {
  produitInfo = {
    produit_id: 'unknown',
    nom_produit: 'Inconnu',
    reference: 'N/A'
  };
}

return {
  json: {
    ...produitInfo,
    error_message: error.message || 'Erreur inconnue lors de la generation promo',
    error_details: JSON.stringify(error, null, 2),
    timestamp: new Date().toISOString()
  }
};

